hits=[]
for base in [R,R.parent/'lanes']:
 for p in base.glob('*/*'):
  if not p.is_file() or p.parent==L or p.suffix not in ['.md','.json','.txt'] or p.stat().st_size>2000000:continue
  if not any(z in p.name.lower() for z in ['result','summary','reject','review','hold','notes']):continue
  try:s=p.read_text()
  except:continue
  m=[{'line':n,'text':z[:5000]} for n,z in enumerate(s.splitlines(),1) if pat.search(z)]
  if m:hits.append({'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'matches':m})
(L/'historical-final.json').write_text(json.dumps(hits,indent=2))
